def langford(n=12):
    seq = [0] * (2 * n)
    def place(k):
        if k == 0:
            return True
        for i in range(2 * n - k - 1):
            if seq[i] == 0 and seq[i + k + 1] == 0:
                seq[i] = k
                seq[i + k + 1] = k
                if place(k - 1):
                    return True
                seq[i] = 0
                seq[i + k + 1] = 0
        return False
    if place(n):
        return seq
    return None

result = langford()
print(result)
